from sympy import S, Sum, sin, cos, pi, oo
from sympy.abc import n

def record(name, expr):
    try:
        r = expr.is_convergent()
    except Exception:
        probe(name, -1.0)
        return
    if r is S.true:
        probe(name, 1.0)
    elif r is S.false:
        probe(name, 0.0)
    else:
        probe(name, 2.0)

record("Sum(sin(n), (n, 1, oo)).is_convergent()",
       Sum(sin(n), (n, 1, oo)))
record("Sum(sin(n)**2 + cos(n)**2 - 1, (n, 1, oo)).is_convergent()",
       Sum(sin(n)**2 + cos(n)**2 - 1, (n, 1, oo)))
record("Sum(sin(pi*n), (n, 1, oo)).is_convergent()",
       Sum(sin(pi*n), (n, 1, oo)))

